CREATE TABLE "session_imprints" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "session_imprints_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"session_id" integer NOT NULL,
	"message_id" integer,
	"run_id" text,
	"subject_kind" text NOT NULL,
	"subject_key" text NOT NULL,
	"before" jsonb,
	"after" jsonb,
	"owner_version" text,
	"audience_before" jsonb,
	"audience_after" jsonb,
	"status" text DEFAULT 'standing' NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "session_imprints_subject_kind_check" CHECK ("session_imprints"."subject_kind" IN ('seat-bench', 'ruleset-conversion', 'deck', 'annex')),
	CONSTRAINT "session_imprints_status_check" CHECK ("session_imprints"."status" IN ('standing', 'settled'))
);
